function validate([letters, target]) {
  if (!Array.isArray(letters) || letters.length < 2 || letters.length > 10000) return 'letters needs 2 to 10^4 letters.';
  const isLetter = c => typeof c === 'string' && /^[a-z]$/.test(c);
  if (!letters.every(isLetter)) return 'Each entry of letters is one lowercase letter.';
  if (!isLetter(target)) return 'target is one lowercase letter.';
  for (let i = 1; i < letters.length; i++) if (letters[i] < letters[i - 1]) return 'letters must be sorted in non-decreasing order.';
  if (letters[0] === letters[letters.length - 1]) return 'letters needs at least two different letters.';
  return null;
}

