function nextGreatestLetter(letters, target) {
  let left = 0;
  let right = letters.length;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (letters[mid] <= target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left === letters.length) {
    return letters[0];
  }
  return letters[left];
}

