function nextGreatestLetter(letters, target) {
  let best = null;
  for (const ch of letters) {
    if (ch.charCodeAt(0) > target.charCodeAt(0) && (best === null || ch.charCodeAt(0) < best.charCodeAt(0))) best = ch;
  }
  return best === null ? letters[0] : best;
}

