function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (lo, hi) => alphabet[lo + Math.floor(rand() * (hi - lo + 1))];
  for (;;) {
    const n = size === 'large' ? 2000 - Math.floor(rand() * 20) : 2 + Math.floor(rand() * 7);
    const lo = Math.floor(rand() * 20);
    const hi = lo + 1 + Math.floor(rand() * (25 - lo));
    const letters = Array.from({ length: n }, () => pick(lo, hi)).sort();
    if (new Set(letters).size < 2) continue;
    return [letters, pick(0, 25)];
  }
}
